Toggle Cheliceraeth.command:
const CONCEALED = "modules/ember/assets/tokens/creatures/CheliceraethHidden.webp";
const VISIBLE = "modules/ember/assets/tokens/creatures/Cheliceraeth.webp";
const updates = [];
for ( const token of canvas.tokens.controlled ) {
  if ( token.document.baseActor.id !== "C8POmQfke7hHRQ9J" ) continue;
  const concealed = token.document.texture.src === CONCEALED;
  const src = concealed ? VISIBLE : CONCEALED;
  const disposition = concealed ? CONST.TOKEN_DISPOSITIONS.HOSTILE : CONST.TOKEN_DISPOSITIONS.SECRET;
  updates.push({_id: token.id, disposition, "texture.src": src});
}
await canvas.scene.updateEmbeddedDocuments("Token", updates);
